begin;
set local search_path=public,extensions;
select plan(47);
grant usage on schema extensions to authenticated,service_role;
grant execute on all functions in schema extensions to authenticated,service_role;

select ok((select count(*)=11 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array[
  'create_vendor','create_vendor_bank_account','submit_purchase_request','issue_purchase_order','confirm_goods_service_receipt',
  'register_supplier_invoice_payable','schedule_outbound_payment','mark_outbound_payment_paid','reconcile_paid_outbound_payment',
  'ingest_verified_own_payment_event','record_provider_commission_receipt'
])),'eleven P0 finance workflow commands exist');
select ok((select count(*)=11 and bool_and(p.prosecdef and p.proconfig::text like '%search_path=%') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array[
  'create_vendor','create_vendor_bank_account','submit_purchase_request','issue_purchase_order','confirm_goods_service_receipt',
  'register_supplier_invoice_payable','schedule_outbound_payment','mark_outbound_payment_paid','reconcile_paid_outbound_payment',
  'ingest_verified_own_payment_event','record_provider_commission_receipt'
])),'all finance commands are security definer with fixed search path');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array[
  'create_vendor','create_vendor_bank_account','submit_purchase_request','issue_purchase_order','confirm_goods_service_receipt',
  'register_supplier_invoice_payable','schedule_outbound_payment','mark_outbound_payment_paid','reconcile_paid_outbound_payment'
]) and (has_function_privilege('anon',p.oid,'EXECUTE') or has_function_privilege('service_role',p.oid,'EXECUTE'))),'human commands deny anon and service role');
select ok((select has_function_privilege('service_role',p.oid,'EXECUTE') and not has_function_privilege('authenticated',p.oid,'EXECUTE') and not has_function_privilege('anon',p.oid,'EXECUTE') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='ingest_verified_own_payment_event'),'verified provider-event ingestion is service-role only');
select ok((select has_function_privilege('service_role',p.oid,'EXECUTE') and not has_function_privilege('authenticated',p.oid,'EXECUTE') and not has_function_privilege('anon',p.oid,'EXECUTE') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='record_provider_commission_receipt'),'verified commission receipt is Matricia service-only');
select ok((select pg_get_functiondef(p.oid) like '%begin_provider_billing_command%' and pg_get_functiondef(p.oid) like '%finish_provider_billing_command%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='submit_purchase_request'),'purchase request command is idempotent');
select ok((select pg_get_functiondef(p.oid) like '%requested_by=a%' and pg_get_functiondef(p.oid) like '%REQUESTER_CANNOT_APPROVE%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='issue_purchase_order'),'order issuance enforces four-eyes');
select ok((select pg_get_functiondef(p.oid) like '%auth.jwt()%' and pg_get_functiondef(p.oid) like '%aal2%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='schedule_outbound_payment'),'outbound scheduling requires AAL2');
select ok((select pg_get_functiondef(p.oid) like '%cooling_until%' and pg_get_functiondef(p.oid) like '%BANK_ACCOUNT_NOT_ACTIVE%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='schedule_outbound_payment'),'outbound scheduling respects active cooled beneficiary version');
select ok((select pg_get_functiondef(p.oid) like '%SCHEDULER_CANNOT_PAY%' and pg_get_functiondef(p.oid) like '%for update%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='mark_outbound_payment_paid'),'payment execution locks and separates scheduler from payer');
select ok((select pg_get_functiondef(p.oid) like '%''DEBIT''%' and pg_get_functiondef(p.oid) like '%''CREDIT''%' and pg_get_functiondef(p.oid) like '%SUPPLIER_PAYMENT%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='mark_outbound_payment_paid'),'supplier payment posts balanced double entry');
select ok((select pg_get_functiondef(p.oid) like '%auth.role()%' and pg_get_functiondef(p.oid) like '%PAYMENT_EVENT_REPLAY_MISMATCH%' and pg_get_functiondef(p.oid) like '%pg_advisory_xact_lock%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='ingest_verified_own_payment_event'),'own-payment webhook is signed-adapter only, serialized and anti-replay');
select ok((select pg_get_functiondef(p.oid) like '%MATRICIA_OWN_REVENUE%' and pg_get_functiondef(p.oid) like '%payment_provider_events%' and pg_get_functiondef(p.oid) like '%matricia_own_revenue_payments%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='ingest_verified_own_payment_event'),'own-payment success has a distinct Matricia revenue ledger');
select ok((select pg_get_functiondef(p.oid) like '%MATRICIA_OWN_REFUND%' and pg_get_functiondef(p.oid) like '%payment_refunds%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='ingest_verified_own_payment_event'),'refund event reverses own revenue through immutable evidence');
select ok((select pg_get_functiondef(p.oid) like '%MATRICIA_OWN_CHARGEBACK%' and pg_get_functiondef(p.oid) like '%payment_disputes%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='ingest_verified_own_payment_event'),'dispute and chargeback paths are explicit');
select ok((select pg_get_functiondef(p.oid) like '%PROVIDER_COMMISSION_RECEIPT%' and pg_get_functiondef(p.oid) like '%provider_payment_allocations%' and pg_get_functiondef(p.oid) like '%p_confirmation_verified%' and pg_get_functiondef(p.oid) not like '%p_cash_account_id%' and pg_get_functiondef(p.oid) like '%''DEBIT''%' and pg_get_functiondef(p.oid) like '%''CREDIT''%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='record_provider_commission_receipt'),'provider commission receipt is confirmed, canonical, balanced and atomically allocated');
select ok((select bool_and(pg_get_functiondef(p.oid) not like '%direct_client_provider_payments%') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array['ingest_verified_own_payment_event','record_provider_commission_receipt'])),'Matricia cash commands never mutate direct client-provider evidence');
select ok((select count(*)=11 and bool_and(pg_get_functiondef(p.oid) like '%audit_events%' and pg_get_functiondef(p.oid) like '%event_outbox%') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array[
  'create_vendor','create_vendor_bank_account','submit_purchase_request','issue_purchase_order','confirm_goods_service_receipt',
  'register_supplier_invoice_payable','schedule_outbound_payment','mark_outbound_payment_paid','reconcile_paid_outbound_payment',
  'ingest_verified_own_payment_event','record_provider_commission_receipt'
])),'every command audits and emits Outbox');
select ok(not exists(select 1 from information_schema.columns where table_schema='public' and table_name=any(array['purchase_requests','purchase_orders','supplier_invoices','accounts_payable','outbound_payments','matricia_own_revenue_payments','provider_commission_receipts']) and data_type in('real','double precision')),'P0 finance workflow stores no floating point money');
select ok((select pg_get_functiondef(p.oid) like '%ACCOUNTANT_REVIEW_REQUIRED%' and pg_get_functiondef(p.oid) like '%tax_rule_version_id%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='register_supplier_invoice_payable'),'supplier invoice command requires versioned tax or accountant review');
select ok(
  (select pg_get_functiondef(p.oid) like '%PAYMENT_OVERALLOCATED%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='schedule_outbound_payment')
  and (select pg_get_functiondef(p.oid) like '%PAYABLE_OVERALLOCATED_OR_NOT_FOUND%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='reconcile_paid_outbound_payment'),
  'outbound payment rejects payable and payment over-allocation');
select ok((select relrowsecurity from pg_class where oid='public.goods_service_receipt_lines'::regclass),'quantified receipt lines are RLS protected');
select ok((select pg_get_functiondef(p.oid) like '%RECEIPT_EXCEEDS_PURCHASE_ORDER_LINE%' from pg_proc p where p.oid='public.confirm_goods_service_receipt(uuid,text,text,date,text,jsonb,text,uuid)'::regprocedure)and(select pg_get_functiondef(p.oid) like '%INVOICE_QUANTITY_EXCEEDS_RECEIPT%' and pg_get_functiondef(p.oid) like '%INVOICE_LINE_PRICE_DOES_NOT_MATCH_PO%' from pg_proc p where p.oid='public.register_supplier_invoice_payable(uuid,text,date,date,char,uuid,text,jsonb,text,uuid)'::regprocedure),'three-way matching binds ordered, received and invoiced line quantities/prices');
select ok((select pg_get_functiondef(p.oid) like '%accounts_payable%for update%' from pg_proc p where p.proname='reconcile_paid_outbound_payment'),'AP reconciliation locks the payable row before balance derivation');
select ok((select pg_get_functiondef(p.oid) like '%OWN_PAYMENT_CURRENCY_MISMATCH%' and pg_get_functiondef(p.oid) like '%CHARGEBACK_EXCEEDS_PAYMENT%' and pg_get_functiondef(p.oid) like '%PAYMENT_DISPUTE_TERMINAL%' from pg_proc p where p.proname='ingest_verified_own_payment_event'),'own-payment corrections enforce currency, cumulative chargeback and terminal states');
select ok((select pg_get_functiondef(p.oid) like '%INVALID_DIRECT_PAYMENT_MISSION_CONTRACT_BINDING%' and pg_get_functiondef(p.oid) like '%public.missions%' and pg_get_functiondef(p.oid) like '%public.contract_versions%' and pg_get_functiondef(p.oid) like '%public.contracts%' and pg_get_functiondef(p.oid) like '%p_client_organization_id%' and pg_get_functiondef(p.oid) like '%p_provider_organization_id%' from pg_proc p where p.proname='record_direct_client_provider_payment'),'direct payment binds mission, contract version, client and provider tenants');

insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values
('a1000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','v41-finance@example.invalid','',now(),'{}','{}',now(),now()),
('a1000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','v41-outsider@example.invalid','',now(),'{}','{}',now(),now());
insert into public.organizations(id,legal_name,display_name,status,created_by)values
('a2000000-0000-0000-0000-000000000001','V41 Matricia Finance','V41 Finance','ACTIVE','a1000000-0000-0000-0000-000000000001'),
('a2000000-0000-0000-0000-000000000002','V41 Other Tenant','Other Tenant','ACTIVE','a1000000-0000-0000-0000-000000000002');
insert into public.platform_user_roles(user_id,role_code)values('a1000000-0000-0000-0000-000000000001','FINANCE_MANAGER');

set local role authenticated;
select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"a1000000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select public.create_vendor('a2000000-0000-0000-0000-000000000001','V41 Vendor','REG-V41','SOFTWARE','STANDARD','vendor-create-v41',extensions.gen_random_uuid())$$,'authorized finance creates a vendor');
select lives_ok($$select public.create_vendor('a2000000-0000-0000-0000-000000000001','V41 Vendor','REG-V41','SOFTWARE','STANDARD','vendor-create-v41',extensions.gen_random_uuid())$$,'vendor command replay is idempotent');
select is((select count(*)from public.vendors where organization_id='a2000000-0000-0000-0000-000000000001'and legal_name='V41 Vendor'),1::bigint,'vendor replay creates one row');
select lives_ok(format('select public.create_vendor_bank_account(%L,%L,extensions.gen_random_uuid())',(select id from public.vendors where legal_name='V41 Vendor'),'vendor-bank-root-v41'),'authorized finance creates a bank-account root');
select lives_ok(format('select public.create_vendor_bank_account(%L,%L,extensions.gen_random_uuid())',(select id from public.vendors where legal_name='V41 Vendor'),'vendor-bank-root-v41'),'bank-account root replay is idempotent');
select is((select count(*)from public.vendor_bank_accounts where vendor_id=(select id from public.vendors where legal_name='V41 Vendor')),1::bigint,'bank-account replay creates one root');
select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claims','{"sub":"a1000000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.create_vendor('a2000000-0000-0000-0000-000000000001','Cross Tenant','REG-X','SOFTWARE','LOW','vendor-denied-v41',extensions.gen_random_uuid())$$,'42501','VENDOR_CREATE_DENIED','outsider cannot mutate another tenant');
select is((select count(*)from public.vendors where organization_id='a2000000-0000-0000-0000-000000000001'),0::bigint,'RLS hides finance vendor rows from outsider');
reset role;

select set_config('request.jwt.claim.sub','',true);
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select lives_ok($$select public.ingest_verified_own_payment_event('a2000000-0000-0000-0000-000000000001','SUBSCRIPTION','SUB-V41-001','CMI','EVENT-PAY-0001','PAYMENT_SUCCEEDED','PAYMENT-0001',10000,'MAD',clock_timestamp(),'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb',null,null,null,extensions.gen_random_uuid())$$,'verified own-payment event is accepted');
select lives_ok($$select public.ingest_verified_own_payment_event('a2000000-0000-0000-0000-000000000001','SUBSCRIPTION','SUB-V41-001','CMI','EVENT-PAY-0001','PAYMENT_SUCCEEDED','PAYMENT-0001',10000,'MAD',clock_timestamp(),'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb',null,null,null,extensions.gen_random_uuid())$$,'exact own-payment replay is accepted once');
select is((select count(*)from public.matricia_own_revenue_payments where provider='CMI'and provider_payment_id='PAYMENT-0001'),1::bigint,'own-payment replay writes one payment');
select ok((select sum(amount_minor)filter(where direction='DEBIT')=sum(amount_minor)filter(where direction='CREDIT')and sum(amount_minor)filter(where direction='DEBIT')=10000 from public.financial_entries where journal_id=(select financial_journal_id from public.matricia_own_revenue_payments where provider_payment_id='PAYMENT-0001')),'own-payment journal is exactly balanced');
select throws_ok($$select public.ingest_verified_own_payment_event('a2000000-0000-0000-0000-000000000001',null,null,'CMI','EVENT-REFUND-USD','REFUND_SUCCEEDED','PAYMENT-0001',1000,'USD',clock_timestamp(),'cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc','dddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddd','refund',null,null,extensions.gen_random_uuid())$$,'23514','OWN_PAYMENT_CURRENCY_MISMATCH','refund currency must equal original payment currency');
select throws_ok($$select public.ingest_verified_own_payment_event('a2000000-0000-0000-0000-000000000001','SUBSCRIPTION','SUB-V41-001','CMI','EVENT-PAY-0001','PAYMENT_SUCCEEDED','PAYMENT-0001',9000,'MAD',clock_timestamp(),'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb',null,null,null,extensions.gen_random_uuid())$$,'22000','PAYMENT_EVENT_REPLAY_MISMATCH','changed webhook replay is rejected');
select lives_ok($$select public.ingest_verified_own_payment_event('a2000000-0000-0000-0000-000000000001',null,null,'CMI','EVENT-CB-0001','CHARGEBACK','PAYMENT-0001',4000,'MAD',clock_timestamp(),'eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee','ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff','chargeback','DISPUTE-0001','1111111111111111111111111111111111111111111111111111111111111111',extensions.gen_random_uuid())$$,'first chargeback is posted');
select throws_ok($$select public.ingest_verified_own_payment_event('a2000000-0000-0000-0000-000000000001',null,null,'CMI','EVENT-CB-TERMINAL','DISPUTE_WON','PAYMENT-0001',4000,'MAD',clock_timestamp(),'1212121212121212121212121212121212121212121212121212121212121212','1313131313131313131313131313131313131313131313131313131313131313',null,'DISPUTE-0001',null,extensions.gen_random_uuid())$$,'55000','PAYMENT_DISPUTE_TERMINAL','terminal chargeback cannot transition again');
select throws_ok($$select public.ingest_verified_own_payment_event('a2000000-0000-0000-0000-000000000001',null,null,'CMI','EVENT-CB-0002','CHARGEBACK','PAYMENT-0001',7000,'MAD',clock_timestamp(),'1414141414141414141414141414141414141414141414141414141414141414','1515151515151515151515151515151515151515151515151515151515151515','chargeback','DISPUTE-0002','1616161616161616161616161616161616161616161616161616161616161616',extensions.gen_random_uuid())$$,'23514','CHARGEBACK_EXCEEDS_PAYMENT','cumulative chargebacks cannot exceed original payment');
reset role;

insert into public.vendor_bank_account_versions(id,organization_id,bank_account_id,version_no,beneficiary_name,masked_coordinates,coordinate_fingerprint,encrypted_coordinates_reference,evidence_hash,status,risk_flag,cooling_until,proposed_by)select'a3000000-0000-0000-0000-000000000001',v.organization_id,b.id,1,'V41 Vendor','****001','1717171717171717171717171717171717171717171717171717171717171717','vault://v41/vendor/1','1818181818181818181818181818181818181818181818181818181818181818','ACTIVE',false,clock_timestamp()-interval'1 day','a1000000-0000-0000-0000-000000000001'from public.vendor_bank_accounts b join public.vendors v on v.id=b.vendor_id where v.legal_name='V41 Vendor';
insert into public.supplier_invoices(id,organization_id,vendor_id,invoice_reference,invoice_date,due_date,currency,subtotal_minor,tax_minor,total_minor,fiscal_status,original_document_hash,status,created_by)select'a4000000-0000-0000-0000-000000000001',organization_id,id,'INV-V41-AP',current_date,current_date+30,'MAD',10000,0,10000,'ACCOUNTANT_REVIEW_REQUIRED','1919191919191919191919191919191919191919191919191919191919191919','REGISTERED','a1000000-0000-0000-0000-000000000001'from public.vendors where legal_name='V41 Vendor';
insert into public.accounts_payable(id,organization_id,supplier_invoice_id,currency,amount_due_minor,due_on,status,created_by)values('a5000000-0000-0000-0000-000000000001','a2000000-0000-0000-0000-000000000001','a4000000-0000-0000-0000-000000000001','MAD',10000,current_date+30,'OPEN','a1000000-0000-0000-0000-000000000001');
insert into public.outbound_payments(id,organization_id,vendor_id,bank_account_version_id,payment_reference,amount_minor,currency,status,correlation_id,created_by)select x.id,'a2000000-0000-0000-0000-000000000001',v.id,'a3000000-0000-0000-0000-000000000001',x.ref,6000,'MAD','SCHEDULED',extensions.gen_random_uuid(),'a1000000-0000-0000-0000-000000000001'from public.vendors v cross join(values('a6000000-0000-0000-0000-000000000001'::uuid,'OUT-V41-1'),('a6000000-0000-0000-0000-000000000002'::uuid,'OUT-V41-2'))x(id,ref)where v.legal_name='V41 Vendor';
insert into public.outbound_payment_schedules(organization_id,outbound_payment_id,accounts_payable_id,scheduled_amount_minor,scheduled_by)values('a2000000-0000-0000-0000-000000000001','a6000000-0000-0000-0000-000000000001','a5000000-0000-0000-0000-000000000001',6000,'a1000000-0000-0000-0000-000000000002'),('a2000000-0000-0000-0000-000000000001','a6000000-0000-0000-0000-000000000002','a5000000-0000-0000-0000-000000000001',6000,'a1000000-0000-0000-0000-000000000002');
insert into public.outbound_payment_state_events(organization_id,outbound_payment_id,event_type,provider_reference,evidence_hash,journal_id,idempotency_key,correlation_id,occurred_at,recorded_by)select'a2000000-0000-0000-0000-000000000001',x.id,'PAID',x.ref,'2020202020202020202020202020202020202020202020202020202020202020',p.financial_journal_id,'paid-'||x.ref,extensions.gen_random_uuid(),clock_timestamp(),'a1000000-0000-0000-0000-000000000002'from public.matricia_own_revenue_payments p cross join(values('a6000000-0000-0000-0000-000000000001'::uuid,'PROVIDER-1'),('a6000000-0000-0000-0000-000000000002'::uuid,'PROVIDER-2'))x(id,ref)where p.provider_payment_id='PAYMENT-0001';
set local role authenticated;
select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a1000000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select public.reconcile_paid_outbound_payment('a6000000-0000-0000-0000-000000000001','reconcile-v41-1',extensions.gen_random_uuid())$$,'first serialized AP reconciliation succeeds');
select throws_ok($$select public.reconcile_paid_outbound_payment('a6000000-0000-0000-0000-000000000002','reconcile-v41-2',extensions.gen_random_uuid())$$,'23514','PAYABLE_OVERALLOCATED_OR_NOT_FOUND','competing AP reconciliation is serialized and rejects over-allocation');
select throws_ok($$select public.record_provider_commission_receipt(extensions.gen_random_uuid(),'PROVIDER-SELF-ATTEST',current_date,'BANK_TRANSFER',100,0,'2121212121212121212121212121212121212121212121212121212121212121',true,'commission-provider-denied',extensions.gen_random_uuid())$$,'42501','permission denied for function record_provider_commission_receipt','authenticated provider or finance user cannot self-attest a Matricia receipt');
select throws_ok($$select public.record_direct_client_provider_payment('a2000000-0000-0000-0000-000000000001','a2000000-0000-0000-0000-000000000002',null,null,10000,1000,'MAD',clock_timestamp(),'BANK_TRANSFER','DIRECT-V41-INVALID',null,'DECLARED','direct-invalid-binding',extensions.gen_random_uuid())$$,'23514','INVALID_DIRECT_PAYMENT_MISSION_CONTRACT_BINDING','direct payment rejects missing or cross-tenant mission and contract binding');
reset role;

select * from finish();
rollback;
